# java_utils — MCP server generated by mcp-forge
# Provides access to public Java utility functions extracted from the codebase, including operations like finding prime numbers, calculating factorials, reversing strings, and summing lists.
#
# Auto-generated — edit as needed.
# IMPORTANT: this server compiles and runs Java methods via subprocess.
#            Make sure 'javac' and 'java' are installed and accessible in your PATH.
#            Each call writes a small driver class next to a COPY of the
#            original source file in a temp directory, compiles both
#            together, runs the result, then deletes the temp directory.
#            Known limitation: only works for a class with no `package`
#            declaration (default package) — a real multi-file project
#            with a package hierarchy is not resolved, only the single
#            file containing the target method.
# To run: python server.py
# To test: mcp dev server.py

from __future__ import annotations

import os
import shutil
import subprocess
import tempfile
from contextvars import ContextVar
from pathlib import Path

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("java_utils")

_request_token: ContextVar[str] = ContextVar("_request_token", default="")

JAVA_SOURCE_DIR = os.environ.get("JAVA_SOURCE_DIR", os.path.join(os.path.dirname(os.path.abspath(__file__)), "source"))


def _java_available() -> bool:
    return shutil.which("javac") is not None and shutil.which("java") is not None


def _java_literal(value: object, jtype: str) -> str:
    """Formate une valeur Python en littéral Java valide pour le type `jtype`
    (ex: "double[]", "int", "String", "boolean") détecté à la découverte."""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (list, tuple)):
        elem_type = jtype[:-2] if jtype.endswith("[]") else "double"
        return "new " + elem_type + "[]{" + ", ".join(_java_literal(v, elem_type) for v in value) + "}"
    if isinstance(value, str):
        escaped = value.replace("\\", "\\\\").replace('"', '\\"')
        return '"' + escaped + '"'
    return repr(value)


def _run_java_driver(script_file: str, class_name: str, call_expr: str, is_void: bool) -> str:
    """Copie le fichier source original dans un répertoire temporaire,
    écrit à côté un petit pilote (`McpForgeDriver.java`) qui appelle
    `call_expr`, compile les deux ensemble et exécute le pilote.

    Le pilote est écrit séparément (pas concaténé dans le même fichier
    comme pour les autres langages compilés de ce projet) car Java exige
    qu'un fichier `X.java` contienne une classe publique nommée EXACTEMENT
    `X` — impossible d'avoir deux classes publiques dans un seul fichier.
    """
    if not _java_available():
        return "Erreur : 'javac'/'java' introuvables dans le PATH."

    source_path = os.path.join(JAVA_SOURCE_DIR, script_file)
    if not os.path.isfile(source_path):
        return f"Erreur : impossible de lire {source_path}"

    tmp_dir = tempfile.mkdtemp(prefix="mcpforge_java_")
    try:
        shutil.copy(source_path, os.path.join(tmp_dir, os.path.basename(script_file)))
        driver_path = os.path.join(tmp_dir, "McpForgeDriver.java")
        body = call_expr + ";" if is_void else "System.out.println(" + call_expr + ");"
        with open(driver_path, "w", encoding="utf-8") as f:
            f.write(
                "public class McpForgeDriver {\n"
                "    public static void main(String[] args) throws Exception {\n"
                "        " + body + "\n"
                "    }\n"
                "}\n"
            )

        compile_result = subprocess.run(
            ["javac", os.path.basename(script_file), "McpForgeDriver.java"],
            capture_output=True, text=True, timeout=30,
            cwd=tmp_dir,
            # Voir server_codebase_scripting.py.j2 pour l'explication de ce
            # shell=True conditionnel (résolution .bat/.cmd sous Windows).
            shell=(os.name == "nt"),
        )
        if compile_result.returncode != 0:
            return f"Erreur de compilation Java : {compile_result.stderr.strip() or compile_result.stdout.strip()}"

        run_result = subprocess.run(
            ["java", "-cp", tmp_dir, "McpForgeDriver"],
            capture_output=True, text=True, timeout=10,
            shell=(os.name == "nt"),
        )
        if run_result.returncode != 0:
            return f"Erreur Java : {run_result.stderr.strip() or run_result.stdout.strip()}"
        return run_result.stdout.strip()
    except subprocess.TimeoutExpired as exc:
        return f"Erreur Java : timeout ({exc})"
    finally:
        shutil.rmtree(tmp_dir, ignore_errors=True)


@mcp.tool(name="check_is_prime")
def check_is_prime(
    n: int,
) -> str:
    """Determines whether a given integer is a prime number. Use this to validate if a number has no divisors other than 1 and itself.
    Args:
        n: The integer to test for primality.
    Returns:
        Résultat de la méthode Java isPrime.
    """
    _args = ", ".join([
        _java_literal(n, "int"),
    ])
    _call_expr = "Utils.isPrime(" + _args + ")"
    return _run_java_driver(
        "Utils.java", "Utils", _call_expr,
        is_void=False,
    )

@mcp.tool(name="calculate_factorial")
def calculate_factorial(
    n: int,
) -> str:
    """Computes the factorial of a non-negative integer. Use this when you need the product of all positive integers up to n.
    Args:
        n: The non-negative integer for which to calculate the factorial.
    Returns:
        Résultat de la méthode Java factorial.
    """
    _args = ", ".join([
        _java_literal(n, "int"),
    ])
    _call_expr = "Utils.factorial(" + _args + ")"
    return _run_java_driver(
        "Utils.java", "Utils", _call_expr,
        is_void=False,
    )

@mcp.tool(name="reverse_string")
def reverse_string(
    s: str,
) -> str:
    """Returns the reverse of the input string. Use this when the character order of a string needs to be inverted.
    Args:
        s: The input string to be reversed.
    Returns:
        Résultat de la méthode Java reverseString.
    """
    _args = ", ".join([
        _java_literal(s, "String"),
    ])
    _call_expr = "Utils.reverseString(" + _args + ")"
    return _run_java_driver(
        "Utils.java", "Utils", _call_expr,
        is_void=False,
    )

@mcp.tool(name="sum_list")
def sum_list(
    numbers: list[float],
) -> str:
    """Calculates the sum of a list of numbers. Use this to compute the total of a collection of numeric values.
    Args:
        numbers: An array of numbers (integers or floats) to be summed.
    Returns:
        Résultat de la méthode Java sumList.
    """
    _args = ", ".join([
        _java_literal(numbers, "double[]"),
    ])
    _call_expr = "Utils.sumList(" + _args + ")"
    return _run_java_driver(
        "Utils.java", "Utils", _call_expr,
        is_void=False,
    )


if __name__ == "__main__":
    import base64
    import hashlib
    import secrets
    import time
    import urllib.parse
    import uvicorn
    from mcp.server.sse import SseServerTransport
    from starlette.applications import Starlette
    from starlette.middleware.cors import CORSMiddleware
    from starlette.requests import Request
    from starlette.responses import HTMLResponse, JSONResponse, RedirectResponse, Response
    from starlette.routing import Mount, Route

    _MCP_SERVER_URL = os.environ.get("MCP_SERVER_URL", "http://localhost:8000")
    _MCP_SERVER_TOKEN = os.environ.get("MCP_SERVER_TOKEN", "")
    _SERVER_NAME = "java_utils"

    _auth_codes: dict[str, dict] = {}
    _AUTH_CODE_TTL = 300

    _rate_buckets: dict[str, list] = {}
    _RATE_LIMIT_MAX = 10
    _RATE_LIMIT_WINDOW = 60

    # ------------------------------------------------------------------
    # redirect_uri whitelist — prevents open redirect attacks
    # Set OAUTH_ALLOWED_REDIRECT_HOSTS=host1.com,host2.com in production.
    # In dev mode (env var absent/empty): only localhost and 127.0.0.1.
    # ------------------------------------------------------------------
    _OAUTH_ALLOWED_REDIRECT_HOSTS = [
        h.strip()
        for h in os.environ.get("OAUTH_ALLOWED_REDIRECT_HOSTS", "").split(",")
        if h.strip()
    ]

    def _validate_redirect_uri(uri: str) -> bool:
        """Return True iff redirect_uri is allowed by the current policy."""
        if not uri:
            return False
        try:
            parsed = urllib.parse.urlparse(uri)
            host = parsed.hostname or ""
            scheme = parsed.scheme
        except Exception:
            return False
        if not _OAUTH_ALLOWED_REDIRECT_HOSTS:
            # Dev mode: localhost and 127.0.0.1 only
            return host in ("localhost", "127.0.0.1") and scheme in ("http", "https")
        # Production: strict whitelist
        return host in _OAUTH_ALLOWED_REDIRECT_HOSTS

    def _check_rate_limit(ip: str) -> bool:
        now = time.time()
        bucket = _rate_buckets.get(ip, [])
        bucket = [t for t in bucket if now - t < _RATE_LIMIT_WINDOW]
        if len(bucket) >= _RATE_LIMIT_MAX:
            _rate_buckets[ip] = bucket
            return False
        bucket.append(now)
        _rate_buckets[ip] = bucket
        return True


